<script setup>
import { computed, onMounted, ref } from 'vue'
import { useRoute } from 'vue-router'
import VChart from 'vue-echarts'
import { use } from 'echarts/core'
import { CanvasRenderer } from 'echarts/renderers'
import { GraphChart } from 'echarts/charts'
import { TooltipComponent, LegendComponent } from 'echarts/components'
import { ElMessage } from 'element-plus'
import { api } from '../api'
import { formatDateTime, zh } from '../localize'
use([CanvasRenderer, GraphChart, TooltipComponent, LegendComponent])

const route=useRoute(),tab=ref('review'),courses=ref([]),courseId=ref(''),documentId=ref(String(route.query.documentId||'')),candidates=ref([]),activeCards=ref([]),due=ref([]),stats=ref(null),graph=ref({nodes:[],edges:[]})
const reviewSession=ref(null),lastReview=ref(null),flipped=ref(false),cardStartedAt=ref(Date.now()),selected=ref([]),editing=ref(null),busy=ref(false),error=ref('')
const currentCard=computed(()=>reviewSession.value?.cards?.[0]||null)
const progress=computed(()=>reviewSession.value?.plannedCount?Math.round(reviewSession.value.reviewedCount/reviewSession.value.plannedCount*100):0)
const graphOption=computed(()=>({tooltip:{formatter:params=>params.data?.tooltip||params.name},series:[{type:'graph',layout:'force',roam:true,label:{show:true},force:{repulsion:210,edgeLength:115},data:graph.value.nodes.map(node=>({id:node.id,name:node.name,value:Math.round(node.mastery*100),symbolSize:38+node.forgettingRisk*22,itemStyle:{color:node.forgettingRisk>.6?'#e05c68':node.forgettingRisk>.3?'#e0a64b':'#46ad7f',borderWidth:3,borderColor:`rgba(80,91,210,${.25+node.forgettingRisk*.7})`},tooltip:`${node.name}<br/>掌握度 ${Math.round(node.mastery*100)}%<br/>可提取性 ${Math.round(node.retrievability*100)}%`})),links:graph.value.edges.map(edge=>({source:edge.source,target:edge.target,label:{show:true,formatter:edge.relation==='PREREQUISITE'?'先修':edge.relation==='PART_OF'?'组成':'相关'}}))}]}))

onMounted(async()=>{try{courses.value=await api.courses();courseId.value=String(route.query.courseId||courses.value[0]?.id||'');await refresh()}catch(e){error.value=e.message}})
async function refresh(){const [candidateValues,activeValues,dueValues,statistics]=await Promise.all([api.flashcards('CANDIDATE',courseId.value),api.flashcards('ACTIVE',courseId.value),api.dueFlashcards(courseId.value),api.memoryStatistics()]);candidates.value=candidateValues;activeCards.value=activeValues;due.value=dueValues;stats.value=statistics;if(courseId.value)graph.value=await api.knowledgeGraph(courseId.value)}
async function generate(){busy.value=true;error.value='';try{await api.generateFlashcards({courseId:courseId.value,documentId:documentId.value||null,limit:10});documentId.value='';tab.value='candidates';await refresh()}catch(e){error.value=e.message}finally{busy.value=false}}
async function approveBatch(){busy.value=true;try{await api.approveFlashcards(selected.value);selected.value=[];await refresh()}catch(e){error.value=e.message}finally{busy.value=false}}
async function approve(id){await api.approveFlashcard(id);await refresh()}
async function reject(id){await api.rejectFlashcard(id);await refresh()}
async function saveEdit(){busy.value=true;try{await api.updateFlashcard(editing.value.id,{front:editing.value.front,back:editing.value.back,knowledgePoint:editing.value.knowledgePoint,cardType:editing.value.cardType});editing.value=null;await refresh()}catch(e){error.value=e.message}finally{busy.value=false}}
async function startReview(){busy.value=true;try{reviewSession.value=await api.startMemoryReview(courseId.value);lastReview.value=null;flipped.value=false;cardStartedAt.value=Date.now()}catch(e){error.value=e.message}finally{busy.value=false}}
async function rate(rating){if(!currentCard.value)return;busy.value=true;try{const seconds=Math.max(1,Math.round((Date.now()-cardStartedAt.value)/1000));const result=await api.reviewFlashcard(reviewSession.value.id,currentCard.value.id,rating,seconds);lastReview.value={...result,rating};ElMessage.success(`已记录，下次复习：${formatDateTime(result.nextDue)}`);reviewSession.value=result.session;flipped.value=false;cardStartedAt.value=Date.now();await refresh()}catch(e){error.value=e.message}finally{busy.value=false}}
async function courseChanged(){reviewSession.value=null;selected.value=[];await refresh()}
</script>

<template><section><div class="section-heading"><div><span class="eyebrow">长期记忆</span><h2>记忆巩固</h2><p>FSRS 目标留存率90%，每天最多20张或15分钟。</p></div><div class="memory-actions"><el-select v-model="courseId" placeholder="选择课程" @change="courseChanged"><el-option v-for="course in courses" :key="course.id" :label="zh(course.name)" :value="course.id"/></el-select><el-button :loading="busy" :disabled="!courseId" @click="generate">从课程资料生成候选卡</el-button></div></div><el-alert v-if="error" class="page-alert" type="error" :title="error" show-icon @close="error=''"/><div v-if="stats" class="memory-metrics"><article><span>今日到期</span><strong>{{stats.dueCards}}</strong></article><article><span>活跃卡片</span><strong>{{stats.activeCards}}</strong></article><article><span>候选卡片</span><strong>{{stats.candidateCards}}</strong></article><article><span>本周留存率</span><strong>{{Math.round(stats.retentionRate*100)}}%</strong></article></div><el-tabs v-model="tab" class="memory-tabs"><el-tab-pane label="今日复习" name="review"><div v-if="!reviewSession" class="memory-start"><h3>到期复习 {{due.length}} 张</h3><p>系统会优先选择可提取性最低和逾期最久的卡片。</p><el-button type="primary" :disabled="!due.length" :loading="busy" @click="startReview">开始今日复习</el-button></div><div v-else-if="reviewSession.status!=='ACTIVE'||!currentCard" class="memory-start"><h3>今日复习完成</h3><p>完成 {{reviewSession.reviewedCount}} / {{reviewSession.plannedCount}} 张，用时 {{Math.round(reviewSession.elapsedSeconds/60)}} 分钟。</p><el-button @click="reviewSession=null">返回</el-button></div><div v-else class="review-stage"><div class="review-progress"><span>{{reviewSession.reviewedCount+1}} / {{reviewSession.plannedCount}}</span><el-progress :percentage="progress"/></div><button class="flashcard-stage" :class="{flipped}" @click="flipped=true"><span class="eyebrow">{{currentCard.knowledgePoint}}</span><h2>{{currentCard.front}}</h2><template v-if="flipped"><div class="flashcard-answer">{{currentCard.back}}</div><div class="card-sources"><span v-for="source in currentCard.sources" :key="source.url||source.filename">{{source.filename||source.title}}<template v-if="source.pageNumber"> 第{{source.pageNumber}}页</template></span></div></template><p v-else>点击显示答案</p></button><div v-if="flipped" class="rating-buttons"><el-button type="danger" :loading="busy" @click="rate('AGAIN')">忘记</el-button><el-button type="warning" :loading="busy" @click="rate('HARD')">困难</el-button><el-button type="primary" :loading="busy" @click="rate('GOOD')">记得</el-button><el-button type="success" :loading="busy" @click="rate('EASY')">轻松</el-button></div></div></el-tab-pane><el-tab-pane :label="`候选卡片 (${candidates.length})`" name="candidates"><div class="candidate-toolbar"><span>候选卡必须确认后才进入复习队列。</span><el-button type="primary" :disabled="!selected.length" :loading="busy" @click="approveBatch">批量确认 {{selected.length}} 张</el-button></div><div class="candidate-list"><article v-for="card in candidates" :key="card.id"><el-checkbox v-model="selected" :value="card.id"/><div class="candidate-main"><strong>{{card.front}}</strong><p>{{card.back}}</p><small>{{card.knowledgePoint}} · {{card.sources.length}} 个来源</small></div><el-button text @click="editing={...card}">编辑</el-button><el-button text type="success" @click="approve(card.id)">确认</el-button><el-button text type="danger" @click="reject(card.id)">拒绝</el-button></article></div><el-empty v-if="!candidates.length" description="暂无候选卡。可以从课程资料生成，或完成一次有错题的测验。"/></el-tab-pane><el-tab-pane label="知识地图" name="graph"><div class="graph-legend"><span class="safe">稳定</span><span class="warn">可能遗忘</span><span class="risk">高风险</span><small>节点颜色表示遗忘风险，数值来自掌握度与FSRS可提取性。</small></div><VChart v-if="graph.nodes.length" class="knowledge-chart" :option="graphOption" autoresize/><el-empty v-else description="确认卡片并完成复习后会形成知识地图。"/></el-tab-pane></el-tabs><el-dialog v-model="editing" title="编辑候选卡" width="560px"><el-form v-if="editing" label-position="top"><el-form-item label="正面"><el-input v-model="editing.front" type="textarea" :rows="3"/></el-form-item><el-form-item label="背面"><el-input v-model="editing.back" type="textarea" :rows="5"/></el-form-item><el-form-item label="知识点"><el-input v-model="editing.knowledgePoint"/></el-form-item><el-form-item label="类型"><el-select v-model="editing.cardType"><el-option v-for="value in ['BASIC','CLOZE','CODE']" :key="value" :value="value" :label="value"/></el-select></el-form-item></el-form><template #footer><el-button @click="editing=null">取消</el-button><el-button type="primary" :loading="busy" @click="saveEdit">保存</el-button></template></el-dialog></section></template>
